function u(t){return!!(t.bogoAutoFree||t.bogoSameAutoFree)}function c(t){const r=t.offerDiscount??0;return(t.totalPrice-r)*t.quantity}function a(t){return t.reduce((r,o)=>r+c(o),0)}function i(t){return t.reduce((r,o)=>r+(o.offerDiscount??0)*o.quantity,0)}function s(t,r){return t.some(e=>u(e))||r.some(e=>e.appliedOffer!=null)?!0:r.reduce((e,n)=>e+(n.offerDiscount??0)*n.quantity,0)>0}function f(t){return t.reduce((r,o)=>u(o)?r:r+o.totalPrice*o.quantity,0)}export{i as a,a as b,f as c,c as d,s as e,u as i};
